        "rules": [
          {
            "id": "a-creation-budget-only-rises-within-the-ceiling",
            "status": "reviewed",
            "summary": "Raising a creation budget is refused unless the new amount is finite, strictly above the current budget and within the ceiling."
          },
          {
            "id": "a-creation-command-must-name-the-current-revision",
            "status": "reviewed",
            "summary": "A creation command is refused as a conflict unless its expected revision equals the stored one."
          },
          {
            "id": "a-creation-makes-at-most-its-tool-call-ceiling",
            "status": "reviewed",
            "summary": "At the tool-call ceiling a creation's tool request is refused and the count does not grow."
