        "context": {
          "id": "run",
          "status": "reviewed",
          "summary": "Owns a Skill trial Run's lifecycle: its state machine, dispatch to a sandbox provider, following execution to completion, and cleanup.",
          "implementation_path": "trial/execution"
        },
        "vocabulary": [
          {
            "id": "run",
            "status": "reviewed",
            "summary": "One requested trial of a single Skill Version against a single frozen Test Case snapshot, within a Workspace, carried out through one or more attempts on a sandbox Provider, and ending in a single terminal status. An attempt is the execution; the Run is the retryable unit whose identity a reassignment does not change."
          },
          {
            "id": "skill-withheld",
            "status": "reviewed",
            "summary": "A Run that does not load the Skill under evaluation, so it measures the same Test Case without that Skill; an evaluation batch can run one beside every trial and compare the two. Not the same thing as a Reference batch."
          }
        ],
        "aggregates": [
          {
            "id": "run",
            "status": "reviewed",
            "summary": null
          }
        ],
        "rules": [
          {
            "id": "a-lost-attempts-model-key-is-revoked-before-reassignment",
            "status": "reviewed",
            "summary": "When a Run's attempt is lost with its provider, the platform asks the model gateway to revoke that attempt's model key before it dispatches the next attempt, so the lost sandbox cannot keep spending on a key the Run no longer uses. A revocation the gateway refuses is counted and left to cleanup, which revokes it again."
          },
          {
            "id": "a-provider-cannot-name-an-artifact-object-outside-its-write-grant",
            "status": "reviewed",
            "summary": "An artifact the provider reports may name only the archive object the platform derived for the attempt; any other object key is refused."
          },
          {
            "id": "a-refusal-waiting-cannot-fix-ends-the-run-after-one-attempt",
            "status": "reviewed",
            "summary": "A provider refusal that is neither unavailable nor full is final, so no further attempt starts."
          },
          {
            "id": "a-run-key-gets-the-tokens-per-minute-in-force-when-issued",
            "status": "reviewed",
            "summary": "Every model gateway key issued for a run attempt gets the tokens-per-minute limit in force when it is issued: the operator-set value in run_rate_limit_setting, or the deployment's when none is set. The limit is not kept in the Run's snapshot, so a change reaches the next attempt of a Run already created."
          },
          {
            "id": "a-run-starts-only-when-its-budget-is-reserved",
            "status": "reviewed",
            "summary": "When a credit ledger is configured, a Run is admitted only if the Workspace can reserve the run budget in force when it is created: the operator-set ceiling in run_model_budget_setting, or the deployment's when none is set. The Run keeps that ceiling in its policy snapshot, and its attempts run under it whatever the setting becomes later; a Workspace that cannot reserve it is refused with credit_balance."
          },
          {
            "id": "a-run-starts-only-when-the-platform-model-budget-left-covers-it",
            "status": "candidate",
            "summary": "A trial Run is admitted only when the gateway's platform-wide model budget, less what is already spent and less the ceiling of every unfinished Run, still covers this Run's ceiling. Otherwise the preflight summary is blocked with platform_model_budget and creating the Run is refused for the same reason: no Run is created and nothing is charged, and the refusal says the budget recovers at 08:00 Taipei time. A budget or count that cannot be read admits the Run, because the gateway still enforces its own budget."
          },
          {
            "id": "a-run-survives-at-most-one-lost-provider",
            "status": "reviewed",
            "summary": "When an attempt's provider is lost the Run is dispatched to another provider once; a second loss fails the Run with provider_error."
          },
          {
            "id": "a-run-whose-spend-was-unreadable-is-read-again-for-a-day",
            "status": "reviewed",
            "summary": "A cleaned Run whose cost was not settled at its real spend is queued for another cleanup by supervision, at most once every 5 minutes, until a read settles it or a day has passed since it finished; a settled Run is never queued for spend again."
          },
          {
            "id": "a-timed-out-run-ends-its-live-attempt",
            "status": "reviewed",
            "summary": "When a Run reaches its deadline while an attempt is still live, the attempt is finished as timed out in the same step that moves the Run to timed_out, whether the deadline is noticed by the Run's own job or by the supervisor; a timed-out Run never leaves a live attempt behind."
          },
          {
            "id": "a-workspace-runs-one-trial-at-a-time",
            "status": "reviewed",
            "summary": "A Workspace may have at most one Run in progress; a further request is refused with the workspace_concurrency reason."
          },
          {
            "id": "an-access-restricted-skill-never-reaches-a-sandbox",
            "status": "reviewed",
            "summary": "A run of a skill under an access restriction is refused when it is created, and a run that was queued before the restriction was set fails as policy_refused at dispatch, before any sandbox receives the package; while the restriction cannot be read the run stays queued."
          },
          {
            "id": "an-allowance-counts-only-its-own-workspaces-runs",
            "status": "reviewed",
            "summary": "A Workspace's run allowance counts only its own runs, so another Workspace's runs never spend it."
          },
