          },
          {
            "id": "a-generation-description-is-8-to-4000-characters",
            "status": "reviewed",
            "summary": "A generation's task description counts characters, not bytes: one shorter than 8 characters without a diagram is refused as blank, one longer than 4000 is refused as too long, and both bounds themselves are accepted; with no description, a diagram is required."
          },
          {
            "id": "a-generation-diagram-is-at-most-4-mb",
            "status": "reviewed",
            "summary": "A diagram attached to a generation must be a non-empty image of an allowed type and at most 4,000,000 bytes; a diagram of exactly that size is accepted."
          },
          {
            "id": "a-generation-takes-at-most-three-references",
            "status": "reviewed",
            "summary": "A generation names at most three reference skills; three are accepted and four are refused before the gateway."
          },
          {
            "id": "a-name-from-another-source-is-not-versioned",
            "status": "reviewed",
            "summary": "A Skill arriving from a plugin or URL is refused as name_held_by_another_source when the same-named Skill's latest version came from a different plugin or URL; the rest of the import proceeds. Uploads without an origin and generated sources are exempt."
          },
          {
            "id": "a-new-version-keeps-the-skills-name",
            "status": "reviewed",
            "summary": "A new version must declare the same name as its Skill; another name is refused as version_name_mismatch and neither a version nor the summary changes."
          },
          {
            "id": "a-skill-inside-a-plugin-is-hashed-over-its-own-files",
            "status": "reviewed",
            "summary": "A Skill that is one directory of a larger package is hashed over its own files only, so the same content hashes the same wherever it sits."
          },
          {
            "id": "a-source-records-the-provenance-its-kind-requires",
            "status": "reviewed",
            "summary": "A version is written only when its source carries the provenance its kind requires: git needs a URL and no generator fields, an upload has neither, a generated source needs a model and prompt version and no URL; anything else is refused with ErrIncompleteProvenance."
          },
          {
            "id": "a-spent-platform-model-budget-refuses-without-counting-the-step",
            "status": "candidate",
            "summary": "When the model gateway refuses a call because its platform-wide budget for the period is spent, the refusal is named as such rather than reported as a broken gateway, and every such refusal is counted for alerting. A creation step refused this way is not counted against the session, the session waits for the person to send again, and only the cost actually incurred is settled; a skill generation or a criteria suggestion refused this way answers 503 saying nothing was charged and that retrying now is refused too; a judgement refused this way settles as failed with a summary naming the spent budget, that it was not charged and that it will be judged again; the evaluation job is snoozed hourly without spending its attempts, and once the budget recovers a new judgement supersedes the failed one, giving up after a bounded number of snoozes. Every such refusal tells the person the budget recovers at 08:00 Taipei time (UTC midnight) each day, which holds only while the gateway's budget period is one day. A refusal of one key's own budget is not this case and stays an ordinary gateway failure."
          },
          {
            "id": "a-taken-down-skill-takes-no-new-version",
            "status": "reviewed",
            "summary": "A taken-down Skill refuses every new version as skill_taken_down and gains no version row; in a re-import of several Skills the others still import."
          },
          {
            "id": "a-workspace-runs-one-generation-at-a-time",
            "status": "reviewed",
            "summary": "A workspace holds at most one generation at a time across every API instance: a second request while a lease is live is refused as in flight, another workspace is unaffected, and an expired lease can be taken over."
          },
          {
            "id": "an-import-fetch-follows-at-most-three-redirects",
            "status": "reviewed",
            "summary": "An import from a URL follows at most three redirects and then stops."
          },
          {
            "id": "an-import-fetch-never-dials-a-non-public-address",
            "status": "reviewed",
            "summary": "An import fetch never connects to a loopback, link-local or metadata address, even through an allowed host name or a redirect."
          },
          {
            "id": "an-import-url-carries-no-query-fragment-or-credentials",
            "status": "reviewed",
            "summary": "An import URL holding a query, a fragment or credentials is refused before any request, without echoing them."
          },
          {
            "id": "an-improvement-to-a-superseded-version-is-refused",
            "status": "reviewed",
            "summary": "Saving an improved version is refused with ErrBaseVersionMoved when the Skill's newest version is no longer the version the improvement was made to; content identical to an existing version is deduplicated first."
          },
          {
            "id": "every-redirect-hop-stays-on-the-host-allow-list",
            "status": "reviewed",
            "summary": "Each redirect of an import fetch is checked against the allowed hosts again, so a redirect off the list is never followed."
          },
          {
            "id": "generated-and-uploaded-skills-do-not-share-a-name",
