        "review_mode": "scm-verified",
        "context": {
          "id": "publishing",
          "status": "reviewed",
          "summary": "Owns who discloses what under which name: a creator's publisher namespace, the publications and Bundles in it, their immutable releases, and the operator reviews that expose a release to search.",
          "implementation_path": "skill/publishing"
        },
        "vocabulary": [],
        "aggregates": [],
        "rules": [
          {
            "id": "a-deleted-skills-publication-name-is-held-ninety-days",
            "status": "reviewed",
            "summary": "When a published Skill is deleted its publication retires; for 90 days after that its old address still answers withdrawn and the publisher cannot give its name to another Skill; after 90 days the name passes to another of the same publisher's Skills and the address follows it."
          },
          {
            "id": "a-publication-name-is-permanent",
            "status": "reviewed",
            "summary": "A Skill that already has a publication cannot be republished under another name; the request is refused as name_is_permanent and the publication keeps its name."
          },
          {
            "id": "a-publication-takes-only-a-version-of-its-own-skill",
            "status": "reviewed",
            "summary": "Publishing a Skill with a version of another Skill is answered not found, so one Skill's gates never pass another Skill's files."
          },
          {
            "id": "a-publisher-name-refuses-reserved-words",
            "status": "reviewed",
            "summary": "A publisher name follows the Skill name shape and must not equal a reserved word once its hyphens are removed; a publication name follows only the shape."
          },
          {
            "id": "a-publishing-request-body-is-at-most-64-kib",
            "status": "reviewed",
            "summary": "Every publishing request reads at most 64 KiB of JSON and refuses a longer body with 400."
          },
          {
            "id": "a-taken-down-skill-cannot-be-published",
            "status": "reviewed",
            "summary": "A Skill an operator took down cannot be published; the request is answered not found and no publication is created."
          },
          {
            "id": "a-version-failing-validation-cannot-be-published",
            "status": "reviewed",
            "summary": "Publishing scans the version's stored package and refuses as validation_blocked when it finds any validation error; no publication is recorded."
          },
          {
            "id": "an-approval-names-the-snapshot-digest-its-reviewer-saw",
            "status": "reviewed",
            "summary": "An approval is refused as stale and records nothing unless it names the search snapshot digest the reviewer saw; a revocation needs no such proof."
          },
          {
