          "implementation_path": "trial/design"
        },
        "vocabulary": [],
        "aggregates": [],
        "rules": [
          {
            "id": "a-continuation-freezes-a-new-snapshot-for-its-new-prompt",
            "status": "reviewed",
            "summary": "Continuing a run freezes a new snapshot of the same Test Case whose content hash covers the new prompt, and leaves the earlier snapshot as it was."
          },
          {
            "id": "a-continuation-prompt-is-held-to-the-prompt-limit",
            "status": "reviewed",
            "summary": "A continued snapshot's prompt may not exceed MaxPromptChars characters, counted as characters, not bytes."
          },
          {
            "id": "a-criteria-suggestion-is-paid-for-by-its-requester",
            "status": "reviewed",
            "summary": "Suggesting acceptance criteria is a model call the user starts, so it is open only to invited accounts, refused before the model is called when the test case already holds the most criteria it may or when the owner's credit balance is below the start threshold for suggest_criteria, and debited by the usage the gateway reported once the model answers; it never proposes more criteria than there is room for."
          },
          {
            "id": "a-dataset-file-is-at-most-25-mb",
            "status": "reviewed",
            "summary": "A dataset file larger than MaxFileBytes is refused before anything is stored; empty and nameless files are refused too."
          },
          {
            "id": "a-dataset-is-deleted-only-through-its-own-test-case",
            "status": "reviewed",
            "summary": "A dataset can be deleted only through the Test Case that owns it; naming another Test Case finds nothing and removes nothing."
          },
          {
            "id": "a-disguised-executable-is-refused",
            "status": "reviewed",
            "summary": "An upload whose leading bytes match an executable or archive signature is refused as an unsupported type, whatever its name."
          },
          {
            "id": "a-rubric-item-addresses-an-existing-criterion",
            "status": "reviewed",
            "summary": "A rubric is accepted only when every item names an existing acceptance criterion, and deleting a criterion removes its rubric item."
          },
          {
            "id": "a-snapshot-hash-covers-the-prompt",
            "status": "reviewed",
            "summary": "A snapshot's content hash covers the prompt with the criteria, datasets, rubric and facts, so any edit freezes a new snapshot and earlier ones stay as they were."
          },
          {
            "id": "a-snapshot-reruns-only-while-its-inputs-are-live",
            "status": "reviewed",
            "summary": "A snapshot can be rerun only while its Test Case is not deleted and every dataset it references exists, is not deleted and has not expired."
          },
          {
            "id": "a-spent-platform-model-budget-refuses-without-counting-the-step",
            "status": "candidate",
            "summary": "When the model gateway refuses a call because its platform-wide budget for the period is spent, the refusal is named as such rather than reported as a broken gateway, and every such refusal is counted for alerting. A creation step refused this way is not counted against the session, the session waits for the person to send again, and only the cost actually incurred is settled; a skill generation or a criteria suggestion refused this way answers 503 saying nothing was charged and that retrying now is refused too; a judgement refused this way settles as failed with a summary naming the spent budget, that it was not charged and that it will be judged again; the evaluation job is snoozed hourly without spending its attempts, and once the budget recovers a new judgement supersedes the failed one, giving up after a bounded number of snoozes. Every such refusal tells the person the budget recovers at 08:00 Taipei time (UTC midnight) each day, which holds only while the gateway's budget period is one day. A refusal of one key's own budget is not this case and stays an ordinary gateway failure."
          },
          {
            "id": "a-test-case-holds-at-most-20-dataset-files",
            "status": "reviewed",
            "summary": "A Test Case holds at most MaxFilesPerTestCase live dataset files; one more is refused and the object already written is removed."
          },
          {
            "id": "a-test-case-holds-at-most-50-criteria",
            "status": "reviewed",
            "summary": "A Test Case holds at most as many acceptance criteria as the judge reads in one evaluation, twenty; one more is refused as over the limit, so no Test Case can carry a criterion the judge would never see."
          },
          {
            "id": "a-test-case-list-limit-is-1-to-101",
            "status": "reviewed",
            "summary": "The test case list takes a limit from 1 to 101 inclusive and defaults to 51, one row more than a page shows so the client can tell whether another page exists; 0, 102, a non-integer and an empty limit are refused, never replaced by the default."
          },
          {
            "id": "a-test-case-list-offset-is-0-to-the-int32-ceiling",
            "status": "reviewed",
            "summary": "The test case list takes an offset from 0 to 2147483647 as a plain decimal integer; a negative, fractional, hexadecimal, empty or larger value is refused rather than read as 0."
          },
          {
            "id": "a-test-cases-datasets-total-at-most-100-mb",
            "status": "reviewed",
            "summary": "All of a Test Case's dataset files together may not exceed MaxTestCaseBytes; an upload past it is refused."
          },
          {
            "id": "a-workspace-purge-keeps-test-cases-a-run-froze",
            "status": "reviewed",
            "summary": "Purging a Workspace erases only the Test Cases no snapshot froze, so past runs keep the Test Case they ran."
          },
          {
            "id": "a-workspace-that-may-not-store-objects-uploads-no-dataset",
            "status": "reviewed",
            "summary": "A Workspace that may not store objects cannot upload a dataset; the upload is answered not found before anything is stored."
