          "implementation_path": "creator/credit"
        },
        "vocabulary": [],
        "aggregates": [],
        "rules": [
          {
            "id": "a-balance-exactly-at-the-start-threshold-may-start",
            "status": "reviewed",
            "summary": "A start is allowed when the balance is at or above the start threshold; one credit below is refused."
          },
          {
            "id": "a-balance-never-goes-below-the-lowest-stored-balance",
            "status": "reviewed",
            "summary": "An entry that would take a balance below MinBalanceCredits is refused with ErrBalanceOutOfRange and nothing is applied; landing exactly on the minimum is applied."
          },
          {
            "id": "a-charge-is-debited-once-per-idempotency-key",
            "status": "reviewed",
            "summary": "Replaying a charge under the same idempotency key reports it as existing and leaves one cost event, one ledger entry and one debit."
          },
          {
            "id": "a-charge-needs-a-kind-a-key-and-a-user",
            "status": "reviewed",
            "summary": "A charge without a kind, an idempotency key or a user is refused as invalid."
          },
          {
            "id": "a-cost-event-needs-a-kind-and-an-idempotency-key",
            "status": "reviewed",
            "summary": "A cost event without a kind or an idempotency key is refused as invalid and nothing is recorded."
          },
          {
            "id": "a-creation-start-threshold-covers-its-first-step",
            "status": "reviewed",
            "summary": "A creation session may start only when the balance also covers its first step: the start threshold is at least the first step's reserve in credits plus the debt floor, whatever the statistics say."
          },
          {
            "id": "a-debt-floor-above-zero-is-refused-at-startup",
            "status": "reviewed",
            "summary": "Configuration refuses a debt floor above zero, which would demand a surplus before any spend."
          },
          {
            "id": "a-grant-key-reused-for-a-different-entry-is-refused",
            "status": "reviewed",
            "summary": "An idempotency key already used for an operator entry is refused with ErrGrantKeyReused when it is presented with another kind or another amount, and the balance is unchanged."
          },
          {
            "id": "a-grant-needs-a-nonzero-amount-a-reason-and-an-accountable-operator",
            "status": "reviewed",
            "summary": "An operator entry is refused when its credits are zero, its trimmed reason is empty, or its user, operator or idempotency key is missing; its kind must be grant, topup or adjustment."
          },
          {
            "id": "a-markup-no-charge-can-use-is-refused-at-startup",
            "status": "reviewed",
            "summary": "Configuration refuses a markup above the largest one a charge can bill, so the service never starts with every call unbillable."
          },
          {
            "id": "a-purged-account-cannot-pass-the-start-check",
            "status": "reviewed",
            "summary": "The start check refuses an account that account facts report missing or purged, before reading any balance."
          },
          {
            "id": "a-purged-or-missing-account-cannot-be-charged-or-granted",
            "status": "reviewed",
            "summary": "When account facts report the user missing or purged, a grant and a charge are refused with ErrAccountGone and nothing is recorded."
          },
          {
            "id": "a-replayed-grant-applies-and-audits-once",
            "status": "reviewed",
            "summary": "Replaying a grant under the same key returns the current balance and writes no second audit event."
