          {
            "rule": "a-new-version-keeps-the-skills-name",
            "contexts": [
              "ingest"
            ],
            "statement": "A new version must declare the same name as its Skill; another name is refused as version_name_mismatch and neither a version nor the summary changes.",
            "via": [
              "interactions/ingest-registry-version-source"
            ]
          },
          {
            "rule": "a-restored-account-is-purged-again-from-the-purge-record",
            "contexts": [
              "identity"
            ],
            "statement": "Replaying the purge record registers an erasure for, and purges at once, every recorded account the database holds alive; it leaves accounts already purged and accounts the database does not hold alone, and fails naming any record it cannot read or any account it could not purge.",
            "via": [
              "interactions/registry-identity-workspace-purge"
            ]
          },
          {
            "rule": "a-run-starts-only-when-the-platform-model-budget-left-covers-it",
            "contexts": [
              "run"
            ],
            "statement": "A trial Run is admitted only when the gateway's platform-wide model budget, less what is already spent and less the ceiling of every unfinished Run, still covers this Run's ceiling. Otherwise the preflight summary is blocked with platform_model_budget and creating the Run is refused for the same reason: no Run is created and nothing is charged, and the refusal says the budget recovers at 08:00 Taipei time. A budget or count that cannot be read admits the Run, because the gateway still enforces its own budget.",
            "via": [
              "interactions/registry-run-preflight-facts"
            ]
          },
          {
            "rule": "a-source-records-the-provenance-its-kind-requires",
            "contexts": [
              "ingest"
            ],
            "statement": "A version is written only when its source carries the provenance its kind requires: git needs a URL and no generator fields, an upload has neither, a generated source needs a model and prompt version and no URL; anything else is refused with ErrIncompleteProvenance.",
            "via": [
              "interactions/ingest-registry-version-source"
            ]
          },
          {
            "rule": "a-taken-down-skill-takes-no-new-version",
            "contexts": [
              "ingest"
            ],
            "statement": "A taken-down Skill refuses every new version as skill_taken_down and gains no version row; in a re-import of several Skills the others still import.",
            "via": [
              "interactions/ingest-registry-version-source"
            ]
          },
          {
            "rule": "account-purge-runs-every-owners-step-or-none",
            "contexts": [
              "identity"
            ],
            "statement": "Purging a deleted account runs the purge step of every Context that keeps data for its workspace (analytics, testlab, run, packaging, creation, eval, publishing, registry, ingest) together with the object listings of testlab, run and packaging; when any of them is missing, the purge refuses to start instead of purging part of the account.",
            "via": [
              "interactions/registry-identity-workspace-purge"
            ]
          },
          {
            "rule": "an-account-purge-is-recorded-outside-the-database-first",
            "contexts": [
              "identity"
            ],
            "statement": "Once an account purge has claimed the account, it records the account in object storage, outside the database, before it removes any file or row; when that record cannot be written the purge stops and the account and its files stay as they were.",
            "via": [
              "interactions/registry-identity-workspace-purge"
            ]
          },
          {
            "rule": "an-improvement-to-a-superseded-version-is-refused",
            "contexts": [
              "ingest"
            ],
            "statement": "Saving an improved version is refused with ErrBaseVersionMoved when the Skill's newest version is no longer the version the improvement was made to; content identical to an existing version is deduplicated first.",
            "via": [
              "interactions/ingest-registry-version-source"
            ]
          },
