            ]
          },
          {
            "rule": "generated-and-uploaded-skills-do-not-share-a-name",
            "contexts": [
              "ingest"
            ],
            "statement": "A name held by a generated Skill takes no uploaded version, and a generated candidate takes no name held by an uploaded Skill; either way the save is refused with ErrGeneratedNameCollision.",
            "via": [
              "interactions/ingest-registry-version-source"
            ]
          },
          {
            "rule": "identical-content-is-recognised-not-versioned-again",
            "contexts": [
              "ingest"
            ],
            "statement": "Saving content whose hash a version of the same Skill already holds returns that version as a duplicate and writes no new version.",
            "via": [
              "interactions/ingest-registry-version-source"
            ]
          },
          {
            "rule": "purge-removes-files-before-rows",
            "contexts": [
              "identity"
            ],
            "statement": "An account's stored files are removed before its database rows are erased, and the rows are erased in one transaction, so a failure leaves rows pointing at missing files that the next sweep can finish, never a file that no row names.",
            "via": [
              "interactions/registry-identity-workspace-purge"
            ]
          },
          {
            "rule": "purge-waits-for-grace-and-quiet-workspace",
            "contexts": [
              "identity"
            ],
            "statement": "An account purge starts only when the deletion request is older than the 30-day grace at the moment of claiming and every Run in each of the Account's workspaces has finished cleanup; otherwise the purge is deferred (not failed) and retried by a later sweep.",
            "via": [
              "interactions/registry-identity-workspace-purge"
            ]
          },
          {
            "rule": "user-started-model-calls-stop-under-a-p1-halt",
            "contexts": [
              "creation",
              "ingest",
              "testlab"
            ],
            "statement": "While a P1 incident halts dispatch, generating a skill, a creation step, a criteria suggestion and the enrichment of an imported version are refused before the model is called and nothing is charged; a creation step that was refused is not counted and the session waits for the person to send again, and an import still completes with its enrichment left pending for the backfill, which picks nothing up until the halt is lifted. An unreadable halt state counts as halted.",
            "via": [
              "interactions/ingest-registry-version-source"
            ]
          }
