      "change": "amended",
      "status": "reviewed",
      "summary": "A publication is offered only while it is published and its Skill exists, is not taken down, is not held and still passes the release gate; otherwise the first failing reason, in the order delisted, withdrawn, taken_down, held, not_redistributable, is reported.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "purge-removes-files-before-rows",
      "change": "amended",
      "status": "reviewed",
      "summary": "An account's stored files are removed before its database rows are erased, and the rows are erased in one transaction, so a failure leaves rows pointing at missing files that the next sweep can finish, never a file that no row names.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "purge-waits-for-grace-and-quiet-workspace",
      "change": "amended",
      "status": "reviewed",
      "summary": "An account purge starts only when the deletion request is older than the 30-day grace at the moment of claiming and every Run in each of the Account's workspaces has finished cleanup; otherwise the purge is deferred (not failed) and retried by a later sweep.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "raising-the-budget-revives-a-failed-creation",
      "change": "amended",
      "status": "reviewed",
      "summary": "Raising the budget of a failed creation returns it to waiting for input; any other state is kept, and no step is queued.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "releasing-an-unengaged-brake-records-nothing",
      "change": "amended",
      "status": "reviewed",
      "summary": "Releasing the brake when none is engaged succeeds without recording a brake-released audit event.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "releasing-requires-a-registered-publisher",
      "change": "amended",
      "status": "reviewed",
      "summary": "A Workspace without a registered publisher name cannot release; the release is refused with ErrNoPublisher.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "remaining-allowance-is-never-negative",
      "change": "amended",
      "status": "reviewed",
      "summary": "The remaining allowance a Workspace sees is clamped at zero; an overspent Workspace reads 0, not a negative number.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "replaying-a-grant-key-applies-and-audits-once",
      "change": "amended",
      "status": "reviewed",
      "summary": "Re-submitting an operator entry under the same idempotency key returns the current balance without applying it or writing a second audit entry.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "republishing-the-same-version-keeps-its-one-release",
      "change": "amended",
      "status": "reviewed",
      "summary": "Publishing the published latest version again, with the same content and the same declared licence, adds no release, so its exposure review is kept; declaring a different licence for that version adds a release.",
      "through": "findings-recite-2026-10-26"
    },
    {
      "asset": "rules",
      "id": "run-activity-classification",
      "change": "amended",
      "status": "reviewed",
      "summary": "A Run's activity item asks for attention when it failed or timed out, is in progress from queued through evaluating, and is recent once it succeeded or was cancelled; a status the Run context does not know asks for attention.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "session-token-stored-only-as-hash",
      "change": "amended",
      "status": "reviewed",
      "summary": "The raw session token exists only in the cookie handed to the user; the platform stores and looks up only its SHA-256 hash.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "start-statistics-older-than-their-shelf-life-are-not-trusted",
      "change": "amended",
      "status": "reviewed",
      "summary": "A start threshold uses recorded cost statistics only while their window ended within the statistics shelf life; older statistics give the fixed fallback, marked estimated.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "taken-down-or-held-skill-is-not-packaged",
      "change": "amended",
      "status": "reviewed",
      "summary": "A Skill that the platform has taken down, or whose content is held for an unresolved license question, cannot be built into a package; the refusal names taken_down or license_hold.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "the-activity-feed-fails-closed-on-an-unreadable-source",
      "change": "amended",
      "status": "reviewed",
      "summary": "If any owner source of the feed cannot be read or is not configured, no partial page is returned; the request fails naming every source that failed.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "the-activity-feed-pages-in-one-total-order",
      "change": "amended",
      "status": "reviewed",
      "summary": "The feed is ordered by priority, then newest first, then kind, then source id, and a cursor resumes strictly after the last item returned, so pages neither repeat nor skip an item.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "the-activity-service-refuses-a-limit-outside-1-to-100",
      "change": "amended",
      "status": "reviewed",
      "summary": "The activity service itself refuses a page limit below 1 or above 100, whatever its caller checked.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "the-catalogue-never-generates-skills",
      "change": "amended",
      "status": "reviewed",
      "summary": "The catalogue workspace never generates skills; a generation request in it is refused before anything else is checked.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "the-default-run-allowance",
      "change": "amended",
      "status": "reviewed",
      "summary": "By default a Workspace may start 5 runs a day and 30 per 30 days, and 20 in its first 30 days.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "the-funnel-counts-downloads-per-workspace-and-other-stages-per-session",
      "change": "amended",
      "status": "reviewed",
      "summary": "The daily funnel counts downloads as distinct Workspaces and every other stage as distinct sessions.",
      "through": "journey-recite-2026-10-25"
    },
    {
      "asset": "rules",
      "id": "the-hard-wall-clock-runs-from-the-first-dispatch",
      "change": "amended",
      "status": "reviewed",
      "summary": "Once a provider has accepted an attempt, the run's deadline is its first dispatch plus the frozen policy's hard wall clock, not its creation time.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "the-release-gate-refuses-unclear-or-blocked-redistribution",
      "change": "amended",
      "status": "reviewed",
      "summary": "A release is refused unless the Skill's redistribution is allowed, or self_supplied or generated with the author's rights statement; a license hold, a blocked licence and an unconfirmed licence are refused whatever the statement.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "the-suggestion-digest-lists-only-criteria-that-did-not-pass",
      "change": "amended",
      "status": "reviewed",
      "summary": "Passed criteria are left out of the suggestion digest, so their evidence cannot be cited for an improvement.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "time-dispatch-was-paused-does-not-count-against-the-slot-wait",
      "change": "amended",
      "status": "reviewed",
      "summary": "A run waiting for a sandbox slot times out only after the slot-wait limit plus every stretch during which dispatch was paused for every provider that could take it; if the halt history cannot be read the run keeps waiting.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "transient-provider-refusals-stop-at-the-attempt-ceiling",
      "change": "amended",
      "status": "reviewed",
      "summary": "Transient provider refusals start at most the configured number of attempts, after which the run fails as a provider error.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "usage-with-unknown-cost-is-recorded-but-never-debited",
      "change": "amended",
      "status": "reviewed",
      "summary": "A charge whose actual cost is unknown is recorded as an estimated cost event and debits no credits; the reserved ceiling is never billed as the cost.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "user-started-model-calls-stop-under-a-p1-halt",
      "change": "amended",
      "status": "reviewed",
      "summary": "While a P1 incident halts dispatch, generating a skill, a creation step, a criteria suggestion and the enrichment of an imported version are refused before the model is called and nothing is charged; a creation step that was refused is not counted and the session waits for the person to send again, and an import still completes with its enrichment left pending for the backfill, which picks nothing up until the halt is lifted. An unreadable halt state counts as halted.",
      "through": "findings-recite-2026-10-26"
    },
    {
      "asset": "rules",
      "id": "while-the-model-holds-the-turn-only-cancel-and-stop-are-accepted",
      "change": "amended",
      "status": "reviewed",
      "summary": "While a creation is queued for or working with the model, only cancel and stop-step are accepted; other commands conflict.",
      "through": "creation-screen-recite-2026-10-26"
    },
    {
      "asset": "rules",
      "id": "withdrawing-curation-is-always-allowed",
      "change": "amended",
      "status": "reviewed",
      "summary": "Withdrawing curation is allowed for any skill, inside a catalogue or not, and clears the curated version.",
      "through": "shifted-recite-2026-10-24"
    },
