          "implementation_path": "trial/improvement"
        },
        "vocabulary": [],
        "aggregates": [],
        "rules": [
          {
            "id": "a-binary-target-gets-no-diff",
            "status": "reviewed",
            "summary": "A target file with a NUL byte in its first 8000 bytes is not diffable, so its suggestion is blocked as diff_unavailable rather than applied unseen."
          },
          {
            "id": "a-finished-run-without-an-evaluation-is-enqueued-again",
            "status": "reviewed",
            "summary": "Every run that finished as succeeded or failed is evaluated even when the event or job that triggers its evaluation exhausted its retries: every 30 minutes, runs that finished more than 30 minutes and less than a day ago and have no evaluation record are enqueued for evaluation again, through the same enqueue that ignores a run whose evaluation job is still live."
          },
          {
            "id": "a-held-skill-gets-no-suggestion-diff",
            "status": "reviewed",
            "summary": "A Skill held for a licensing question gets no reproduced diff and no version from its suggestions; the block is decided before any file is read."
          },
          {
            "id": "a-pass-is-never-recorded-on-incomplete-evidence",
            "status": "reviewed",
            "summary": "A passed criterion is recorded as undetermined when the trace is incomplete, the input was cut, or the evidence rests on a trimmed source."
          },
          {
            "id": "a-quote-under-twelve-runes-cannot-be-suggestion-evidence",
            "status": "reviewed",
            "summary": "A quote shorter than twelve characters cannot be matched to a verified excerpt as suggestion evidence."
          },
          {
            "id": "a-repeated-suggestion-id-in-an-apply-counts-once",
            "status": "reviewed",
            "summary": "An apply request that names the same suggestion twice applies it once."
          },
          {
            "id": "a-spent-platform-model-budget-refuses-without-counting-the-step",
            "status": "candidate",
            "summary": "When the model gateway refuses a call because its platform-wide budget for the period is spent, the refusal is named as such rather than reported as a broken gateway, and every such refusal is counted for alerting. A creation step refused this way is not counted against the session, the session waits for the person to send again, and only the cost actually incurred is settled; a skill generation or a criteria suggestion refused this way answers 503 saying nothing was charged and that retrying now is refused too; a judgement refused this way settles as failed with a summary naming the spent budget, that it was not charged and that it will be judged again; the evaluation job is snoozed hourly without spending its attempts, and once the budget recovers a new judgement supersedes the failed one, giving up after a bounded number of snoozes. Every such refusal tells the person the budget recovers at 08:00 Taipei time (UTC midnight) each day, which holds only while the gateway's budget period is one day. A refusal of one key's own budget is not this case and stays an ordinary gateway failure."
          },
          {
            "id": "a-suggestion-applies-only-to-the-bytes-it-was-written-for",
            "status": "reviewed",
            "summary": "A suggestion applies only while its target file in the newest version is byte-identical to the version it was written against; otherwise it is blocked as target_changed."
          },
          {
            "id": "a-suggestion-decision-is-accepted-or-rejected",
            "status": "reviewed",
            "summary": "A suggestion decision must be accepted or rejected; pending or any other word is refused as not_a_choice."
          },
          {
            "id": "a-suggestion-of-another-evaluation-cannot-be-applied-through-this-one",
            "status": "reviewed",
            "summary": "A suggestion that belongs to another evaluation is not found when applied through this one."
          },
          {
            "id": "a-suggestion-path-stays-inside-the-package",
            "status": "reviewed",
            "summary": "A suggestion's target must be a clean relative path inside the Skill package; empty, absolute, traversing or uncleaned paths are refused, not repaired."
          },
          {
            "id": "a-suggestion-target-file-is-at-most-1-mib",
            "status": "reviewed",
            "summary": "A file a suggestion targets is read for a reviewable diff only up to 1 MiB; a larger file is refused before any content check."
          },
