      "through": "findings-recite-2026-10-26"
    },
    {
      "asset": "rules",
      "id": "generation-and-run-allowances-are-separate",
      "change": "added",
      "status": "reviewed",
      "summary": "Generations and runs have separate allowances: a spent generation allowance refuses with ErrGenerateQuotaExceeded, never the run refusal, and the reverse.",
      "through": "policy-harvest-rules-2026-10-17"
    },
    {
      "asset": "rules",
      "id": "hybrid-hits-rank-exact-name-then-covered-then-nearest",
      "change": "added",
      "status": "reviewed",
      "summary": "Hybrid results are ordered exact name first, then lexically covered, then vector-ranked by nearest distance, with unranked last and the skill id as the final tiebreak.",
      "through": "catalog-search-rules-2026-10-18"
    },
    {
      "asset": "rules",
      "id": "identical-content-is-recognised-not-versioned-again",
      "change": "added",
      "status": "reviewed",
      "summary": "Saving content whose hash a version of the same Skill already holds returns that version as a duplicate and writes no new version.",
      "through": "findings-recite-2026-10-26"
    },
    {
      "asset": "rules",
      "id": "info-findings-are-kept-out-of-the-suggestion-digest",
      "change": "added",
      "status": "reviewed",
      "summary": "Informational findings are left out of the suggestion digest, so a disclosure cannot be quoted as proof of a problem.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "known-secrets-of-sixteen-bytes-are-scrubbed",
      "change": "added",
      "status": "reviewed",
      "summary": "A known secret such as the Run's own ingestion token is scrubbed from every payload when it is at least 16 bytes long; shorter known values are left alone so ordinary text is not redacted.",
      "through": "trace-harvest-rules-2026-10-17"
    },
    {
      "asset": "rules",
      "id": "no-model-call-without-citable-evidence",
      "change": "added",
      "status": "reviewed",
      "summary": "When the verdict yields no citable evidence, suggestions are not requested and nothing is paid.",
      "through": "suggestion-outcome-recite-2026-10-23"
    },
    {
      "asset": "rules",
      "id": "nothing-applicable-builds-no-version",
      "change": "added",
      "status": "reviewed",
      "summary": "When every selected suggestion is blocked, the apply returns the rejections and builds no version.",
      "through": "eval-suggestion-and-judging-rules-2026-10-18"
    },
    {
      "asset": "rules",
      "id": "nothing-is-collected-without-a-retention-period",
      "change": "added",
      "status": "reviewed",
      "summary": "No funnel event is collected and no analytics cookie is set unless a retention period of at least one second is configured.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "one-import-admits-a-name-once",
      "change": "added",
      "status": "reviewed",
      "summary": "When two directories of one source declare the same Skill name, the first keeps it and the later ones are refused with a duplicate-name finding naming the first path, instead of silently becoming its next version.",
      "through": "ingest-harvest-rules-2026-10-17"
    },
    {
      "asset": "rules",
      "id": "one-import-creates-at-most-fifty-skills",
      "change": "added",
      "status": "reviewed",
      "summary": "One import may create at most MaxSkillsPerImport (50) Skills; a source that would create more is refused as a whole, naming the count it would create and the ceiling. Skills refused for other reasons do not count.",
      "through": "ingest-harvest-rules-2026-10-17"
    },
    {
      "asset": "rules",
      "id": "one-live-account-per-email",
      "change": "added",
      "status": "reviewed",
      "summary": "Two live accounts never share an email: emails are compared after trimming and lower-casing, a sign-up whose email belongs to a live account is refused, and an email held only by a deleted account can be used again.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "only-a-catalogue-skill-can-be-curated",
      "change": "added",
      "status": "reviewed",
      "summary": "Curating a skill is refused when it is not in a catalogue Workspace, and its tier is unchanged.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "only-a-curated-listing-names-its-reviewed-version",
      "change": "added",
      "status": "reviewed",
      "summary": "A listing records a curated version only when the Skill's tier is curated; any other tier writes none.",
      "through": "findings-recite-2026-10-26"
    },
    {
      "asset": "rules",
      "id": "only-a-generated-skill-declares-a-licence-on-its-release",
      "change": "added",
      "status": "reviewed",
      "summary": "An author may declare a licence when releasing a Skill only if the Skill was generated for them, and only one of the known SPDX identifiers, spelled exactly; the declaration is kept on that release.",
      "through": "publishing-generated-skill-declares-a-licence-2026-10-20"
    },
    {
      "asset": "rules",
      "id": "only-a-met-trial-counts-as-passed",
      "change": "added",
      "status": "reviewed",
      "summary": "A trial counts as passed only when its outcome is met; a partially met trial is judged but not passed.",
      "through": "batch-report-counting-and-scope-rules-2026-10-19"
    },
    {
      "asset": "rules",
      "id": "only-a-pending-evaluation-settles",
      "change": "added",
      "status": "reviewed",
      "summary": "An evaluation settles only while it awaits the judge; a second verdict on a settled evaluation is refused, so the first stands.",
      "through": "eval-harvest-rules-2026-10-17"
    },
    {
      "asset": "rules",
      "id": "only-a-runs-own-failures-count-against-the-quota",
      "change": "added",
      "status": "reviewed",
      "summary": "A Run counts against the Workspace's quota only from preparing onward, and not when it failed with provider_error, platform_error, capability_mismatch, policy_refused or resource_limit.",
      "through": "run-harvest-rules"
    },
    {
      "asset": "rules",
      "id": "only-a-succeeded-tool-call-counts-as-success",
      "change": "added",
      "status": "reviewed",
      "summary": "A tool call counts as a success only when its outcome is succeeded.",
      "through": "trace-envelope-paging-and-summary-rules-2026-10-18"
    },
    {
      "asset": "rules",
      "id": "only-actionable-suggestion-categories-are-stored",
      "change": "added",
      "status": "reviewed",
      "summary": "Only skill, runtime, tool and dataset suggestions are stored; MCP and unknown categories are dropped.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "only-an-adjustment-may-lower-a-balance",
      "change": "added",
      "status": "reviewed",
      "summary": "An operator entry with negative credits is refused with ErrGrantLowersBalance unless it is an adjustment.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "only-an-enriched-or-embedded-document-is-listable",
      "change": "added",
      "status": "reviewed",
      "summary": "A search document is listable only once its enrichment is finished or it has an embedding a vector search can find. An enrichment whose embedding call failed is still stored as enriched, without a vector, so it is listable at once; the enrichment backfill later embeds that stored text without calling the enrichment model again, and stores the vector only if the document has not been rewritten since it was claimed.",
      "through": "findings-recite-2026-10-26"
    },
    {
      "asset": "rules",
      "id": "only-judged-trials-enter-the-pass-rate",
      "change": "added",
      "status": "reviewed",
      "summary": "Only judged trials enter a pass rate; running, pending, awaiting-answer and not-evaluated trials count in neither its numerator nor its denominator.",
      "through": "batch-report-counting-and-scope-rules-2026-10-19"
    },
    {
      "asset": "rules",
      "id": "only-public-http-urls-without-credentials-are-fetched",
      "change": "added",
      "status": "reviewed",
      "summary": "Only http or https URLs with a public host and no credentials can be fetched; a literal private address is refused.",
      "through": "creation-harvest-rules-2026-10-17"
    },
    {
