          },
          {
            "id": "a-session-ends-at-its-expiry-instant",
            "status": "reviewed",
            "summary": "A session counts only strictly before its expiry; at the expiry instant it is already signed out."
          },
          {
            "id": "a-session-workspace-answers-only-for-its-owner",
            "status": "reviewed",
            "summary": "The Workspace carried by a signed-in request is reused only when asking about its own owner; any other account's Workspace is read from its owner."
          },
          {
