          },
          {
            "id": "an-operator-erasure-skips-the-deletion-grace",
            "status": "reviewed",
            "summary": "An operator may register an erasure for an account on its holder's behalf, with a reason; it requests deletion if none is pending, keeps an earlier request time, and lets the next purge sweep take the account without waiting out the 30-day grace. The holder cancelling the deletion withdraws it, and an account already purging or deleted refuses it."
          },
          {
            "id": "an-unverified-github-email-never-logs-in",
            "status": "reviewed",
            "summary": "A GitHub login whose profile carries no email is refused when no address is both primary and verified, so an unverified address can never claim an account."
          },
          {
            "id": "deletion-irreversible-once-purge-starts",
            "status": "reviewed",
            "summary": "Once an Account has started purging or is deleted, deletion can neither be requested nor cancelled; the user is told it is irreversible (HTTP 409)."
          },
          {
            "id": "deletion-request-starts-30-day-grace-and-is-idempotent",
            "status": "reviewed",
            "summary": "Requesting account deletion starts a 30-day grace period during which the Account stays fully usable; asking again keeps the original request time instead of extending the wait, and cancelling clears the request and is harmless when nothing is pending."
          },
          {
            "id": "dev-login-exists-only-when-enabled",
