      "model": {
        "usage": "constraint",
        "review_mode": "scm-verified",
        "context": {
          "id": "policy",
          "status": "reviewed",
          "summary": "Owns what a Workspace may consume and how long what it produces is kept: run and generation allowances, and download artifact retention.",
          "implementation_path": "product/entitlements"
        },
        "vocabulary": [],
        "aggregates": [],
        "rules": [
          {
            "id": "a-spent-daily-allowance-refuses-the-next-run",
            "status": "reviewed",
            "summary": "A Workspace that has used its daily allowance in the trailing 24 hours is refused with reason quota_daily, and the message says when it resets."
          },
          {
            "id": "a-spent-window-allowance-refuses-the-next-run",
            "status": "reviewed",
            "summary": "A Workspace that has used its rolling-window allowance is refused with reason quota_window, and the message says when the next one frees up."
          },
          {
            "id": "a-window-allowance-resets-a-window-after-its-oldest-run",
            "status": "reviewed",
            "summary": "A spent window allowance frees its next run one window after the oldest run it still counts."
          },
          {
            "id": "a-young-workspace-has-the-first-window-allowance",
            "status": "reviewed",
            "summary": "Until a Workspace's first window ends, its window ceiling is the first-window allowance, and its window resets at the earlier of that end and the rolling reset; from the moment the first window ends the ordinary window ceiling applies."
          },
          {
            "id": "a-young-workspace-resets-at-the-earlier-boundary",
            "status": "reviewed",
            "summary": "While a Workspace is in its first window, its allowance resets at whichever comes first, the end of that first window or the rolling window's reset."
          },
          {
            "id": "an-allowance-needs-a-window-and-a-ceiling",
            "status": "reviewed",
            "summary": "An allowance is enforced only when it has a window length and at least one ceiling; a zero or partial configuration refuses nothing."
          },
          {
            "id": "an-uncountable-allowance-refuses-without-claiming-it-ran-out",
            "status": "reviewed",
            "summary": "When usage cannot be counted the request is refused with ErrAllowanceUnavailable and a *_unavailable reason; it is never read as unused and never reported as exhausted."
          },
          {
            "id": "download-retention-must-be-positive",
            "status": "reviewed",
            "summary": "Download retention must be a positive duration; zero or negative is refused with ErrRetentionNotConfigured rather than meaning keep forever or delete at once."
          },
          {
            "id": "generation-and-run-allowances-are-separate",
            "status": "reviewed",
            "summary": "Generations and runs have separate allowances: a spent generation allowance refuses with ErrGenerateQuotaExceeded, never the run refusal, and the reverse."
          },
          {
            "id": "remaining-allowance-is-never-negative",
            "status": "reviewed",
            "summary": "The remaining allowance a Workspace sees is clamped at zero; an overspent Workspace reads 0, not a negative number."
          },
          {
            "id": "the-daily-allowance-counts-the-last-24-hours",
            "status": "reviewed",
            "summary": "The daily allowance counts the runs of the 24 hours before now, not of the calendar day."
          },
          {
            "id": "the-default-generation-allowance",
            "status": "reviewed",
            "summary": "By default a Workspace may generate 10 skills a day and 30 per 30 days, and 20 in its first 30 days; the daily generation allowance is higher than the daily run allowance."
          },
          {
            "id": "the-default-run-allowance",
            "status": "reviewed",
            "summary": "By default a Workspace may start 5 runs a day and 30 per 30 days, and 20 in its first 30 days."
          },
          {
            "id": "the-window-allowance-counts-the-last-window-of-days",
            "status": "reviewed",
            "summary": "The window allowance counts the runs of the configured number of days before now, a rolling window rather than a calendar month."
          },
          {
            "id": "when-both-allowances-are-spent-the-daily-reason-is-given",
            "status": "reviewed",
            "summary": "When the daily and the window allowance are both spent, the refusal names the daily allowance and when it resets."
          }
        ],
