        "rules": [
          {
            "id": "a-deleted-skill-is-purged-only-after-its-grace",
            "status": "reviewed",
            "summary": "A deletion sweep purges a Skill and its versions only once the Skill's deletion is older than the grace period; a sweep given a non-positive grace is refused and purges nothing."
          },
          {
            "id": "a-diff-refuses-a-version-of-another-skill",
            "status": "reviewed",
            "summary": "A version diff finds nothing when a named version belongs to another skill, even in the same Workspace."
          },
          {
            "id": "a-fork-carries-its-sources-access-restriction",
            "status": "reviewed",
            "summary": "A fork starts with its source's access restriction, so forking cannot get around a licensing hold."
          },
          {
            "id": "a-fork-name-series-stays-flat",
            "status": "reviewed",
            "summary": "A fork of a fork reuses the base name instead of growing it, treating only an ordinal of two or more as a series number."
          },
          {
            "id": "a-generated-skill-takes-only-generated-content",
            "status": "reviewed",
            "summary": "A version of uploaded content cannot be added to a generated skill; it is refused as a name collision and consumes no version number."
          },
          {
            "id": "a-generated-skills-redistribution-is-permanent",
            "status": "reviewed",
            "summary": "A generated skill's redistribution can be neither blocked nor allowed; it stays generated."
          },
          {
            "id": "a-held-skill-is-not-purged",
            "status": "reviewed",
            "summary": "A purge keeps the row of a skill that has test cases or a version referenced by a run, a download or a bundle; the deleted-skill sweep also keeps a skill while its publication is unretired or retired less than the ninety-day name hold ago, and while an operator takedown or access restriction is in force on it. An operator can take down or restrict a skill its owner has deleted until the sweep purges it, and the operator's skill search lists such a skill with when it was deleted."
          },
          {
            "id": "a-licensing-hold-reaches-forks-through-their-lineage",
            "status": "reviewed",
            "summary": "A Skill without its own access restriction carries the nearest restricted ancestor's along its fork lineage, so a hold placed after a fork was made still holds the fork, without the fork's row being written."
          },
          {
            "id": "a-release-needs-the-licence-the-newest-version-records",
            "status": "reviewed",
            "summary": "Releasing a skill for redistribution is refused when the claimed licence differs from the one its newest version records, and the stored value is unchanged."
          },
          {
            "id": "a-restricted-skill-shows-no-diff",
