    {
      "asset": "rules",
      "id": "a-continuation-prompt-is-held-to-the-prompt-limit",
      "change": "added",
      "status": "reviewed",
      "summary": "A continued snapshot's prompt may not exceed MaxPromptChars characters, counted as characters, not bytes.",
      "through": "testlab-harvest-rules-2026-10-17"
    },
    {
      "asset": "rules",
      "id": "a-corrected-search-is-at-most-2000-characters-combined",
      "change": "added",
      "status": "reviewed",
      "summary": "A search the person corrected is refused when its intent fields and keywords together exceed 2000 characters; exactly 2000 is accepted.",
