    {
      "asset": "rules",
      "id": "a-creation-selects-at-most-three-references",
      "change": "added",
      "status": "reviewed",
      "summary": "Selecting more than three reference Skills is refused.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "a-creation-session-outlives-its-last-step",
      "change": "added",
      "status": "reviewed",
      "summary": "Creation limits are usable only when the retention outlasts the session timeout plus the longest step that can start just before it: the call timeout, ten seconds of slack and sixty seconds to revoke the key, search ahead and settle; otherwise a session row could be deleted before its last step's spend is charged.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "a-creation-start-threshold-covers-its-first-step",
      "change": "added",
      "status": "reviewed",
      "summary": "A creation session may start only when the balance also covers its first step: the start threshold is at least the first step's reserve in credits plus the debt floor, whatever the statistics say.",
      "through": "credit-start-covers-the-first-step-2026-10-20"
    },
    {
      "asset": "rules",
      "id": "a-creation-takes-at-most-its-approved-steps",
      "change": "added",
      "status": "reviewed",
      "summary": "A creation may take a step only while it has taken fewer than its approved number of steps, even with budget left.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "a-criteria-suggestion-is-paid-for-by-its-requester",
      "change": "added",
      "status": "reviewed",
      "summary": "Suggesting acceptance criteria is a model call the user starts, so it is open only to invited accounts, refused before the model is called when the test case already holds the most criteria it may or when the owner's credit balance is below the start threshold for suggest_criteria, and debited by the usage the gateway reported once the model answers; it never proposes more criteria than there is room for.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "a-daily-report-must-have-items",
      "change": "added",
      "status": "reviewed",
      "summary": "A daily report with no items is rejected.",
      "through": "operations-findings-proposals-and-runs-rules-2026-10-18"
    },
    {
      "asset": "rules",
      "id": "a-dataset-file-is-at-most-25-mb",
      "change": "added",
      "status": "reviewed",
      "summary": "A dataset file larger than MaxFileBytes is refused before anything is stored; empty and nameless files are refused too.",
      "through": "testlab-harvest-rules-2026-10-17"
    },
    {
      "asset": "rules",
      "id": "a-dataset-is-deleted-only-through-its-own-test-case",
      "change": "added",
      "status": "reviewed",
      "summary": "A dataset can be deleted only through the Test Case that owns it; naming another Test Case finds nothing and removes nothing.",
      "through": "testlab-snapshot-and-dataset-rules-2026-10-18"
    },
    {
      "asset": "rules",
      "id": "a-debt-floor-above-zero-is-refused-at-startup",
      "change": "added",
      "status": "reviewed",
      "summary": "Configuration refuses a debt floor above zero, which would demand a surplus before any spend.",
      "through": "credit-ledger-rules-2026-10-18"
    },
    {
      "asset": "rules",
      "id": "a-deleted-skill-is-purged-only-after-its-grace",
      "change": "added",
      "status": "reviewed",
      "summary": "A deletion sweep purges a Skill and its versions only once the Skill's deletion is older than the grace period; a sweep given a non-positive grace is refused and purges nothing.",
      "through": "shifted-recite-2026-10-24"
    },
    {
      "asset": "rules",
      "id": "a-deleted-skills-publication-name-is-held-ninety-days",
      "change": "added",
      "status": "reviewed",
      "summary": "When a published Skill is deleted its publication retires; for 90 days after that its old address still answers withdrawn and the publisher cannot give its name to another Skill; after 90 days the name passes to another of the same publisher's Skills and the address follows it.",
