    },
    {
      "asset": "rules",
      "id": "a-held-skill-gets-no-suggestion-diff",
      "change": "added",
      "status": "reviewed",
      "summary": "A Skill held for a licensing question gets no reproduced diff and no version from its suggestions; the block is decided before any file is read.",
