          "status": "reviewed",
          "summary": "Owns Run trace evidence: masking, storing and reading what a Skill trial actually did.",
          "implementation_path": "trial/evidence"
        },
        "vocabulary": [],
        "aggregates": [],
        "rules": [
          {
            "id": "a-refused-trace-event-does-not-fail-its-batch",
            "status": "reviewed",
            "summary": "An invalid event is counted as rejected and skipped; the other events in the same batch are still stored."
          },
          {
            "id": "a-started-run-without-sandbox-events-is-incomplete",
            "status": "reviewed",
            "summary": "A trace is not complete when the run started but no sandbox stream exists; a run that never started is not flagged."
          },
          {
            "id": "a-trace-attempt-is-1-to-100000",
            "status": "reviewed",
            "summary": "An event's attempt must be from 1 to 100000; a larger attempt is refused."
          },
          {
            "id": "a-trace-cursor-must-be-a-non-negative-number",
            "status": "reviewed",
            "summary": "A trace cursor that is negative or not a number answers 400 in every view."
          },
          {
            "id": "a-trace-event-falls-in-its-attempts-window",
            "status": "reviewed",
            "summary": "An event's time must fall between a few minutes in the future and the token's lifetime in the past; epoch or far-future timestamps are refused."
          },
          {
            "id": "a-trace-event-must-belong-to-its-tokens-attempt",
            "status": "reviewed",
            "summary": "An event whose run_id or attempt differs from the ingestion token's grant is refused and counted as rejected."
          },
          {
            "id": "a-trace-ingestion-batch-holds-at-most-1000-events",
            "status": "reviewed",
            "summary": "One trace ingestion request carries at most 1000 events; a larger batch is refused with 413 before any event is judged."
          },
          {
            "id": "a-trace-payload-is-at-most-96-kib",
            "status": "reviewed",
            "summary": "A trace event whose payload exceeds 96 KiB is refused as invalid; exactly 96 KiB is accepted."
          },
          {
            "id": "a-trace-payload-matches-its-types-schema",
            "status": "reviewed",
            "summary": "Each event type declares its payload schema; missing required fields, wrong kinds, values outside an enum and undeclared fields on a closed type are refused."
          },
          {
            "id": "a-trace-producer-must-be-known",
            "status": "reviewed",
            "summary": "An event whose emitted_by is not a known producer is refused."
          },
          {
            "id": "a-trace-schema-must-be-major-version-1",
            "status": "reviewed",
            "summary": "An event is accepted only under a 1.x schema version; another major version is refused while additive minor versions are accepted."
          },
          {
            "id": "a-trace-seq-is-1-to-100000",
            "status": "reviewed",
            "summary": "An event's seq must be from 1 to 100000; a larger seq is refused."
          },
          {
            "id": "a-trace-status-must-be-a-known-outcome",
            "status": "reviewed",
            "summary": "An event whose status is not one of the known outcomes is refused."
          },
          {
            "id": "a-valid-run-total-replaces-summed-usage",
            "status": "reviewed",
            "summary": "Reported usage takes a readable run_total figure field by field and otherwise sums the per-call figures."
          },
          {
            "id": "a-value-under-a-secret-key-is-redacted",
            "status": "reviewed",
            "summary": "Any value under a JSON key whose name denotes a secret, such as password, token, api key, authorization or cookie, is stored as [REDACTED] and its path is reported as masked."
          },
          {
            "id": "an-ingestion-token-admits-only-sandbox-events",
            "status": "reviewed",
            "summary": "An event sent under a sandbox ingestion token is refused unless the sandbox emitted it; orchestrator and llm_service events cannot arrive that way."
          },
          {
            "id": "an-ingestion-token-expires",
            "status": "reviewed",
            "summary": "A trace ingestion token is a signed grant for one Run attempt; it expires after its time to live, and a tampered or expired token is refused."
          },
          {
            "id": "an-oversized-trace-batch-answers-413",
            "status": "reviewed",
            "summary": "A trace ingestion body over 4 MiB answers 413 as too large, apart from a body that fails while being read, which answers 400."
          },
          {
            "id": "evaluation-events-come-only-from-the-orchestrator",
            "status": "reviewed",
            "summary": "evaluation_started and evaluation_completed events are refused unless the orchestrator emitted them, even from an otherwise known producer."
          },
          {
            "id": "evaluation-evidence-holds-at-most-500-tail-events",
            "status": "reviewed",
            "summary": "The evidence an evaluation reads holds at most the last 500 events and is marked truncated and incomplete when more exist."
          },
          {
            "id": "known-secrets-of-sixteen-bytes-are-scrubbed",
            "status": "reviewed",
            "summary": "A known secret such as the Run's own ingestion token is scrubbed from every payload when it is at least 16 bytes long; shorter known values are left alone so ordinary text is not redacted."
          },
          {
            "id": "only-a-succeeded-tool-call-counts-as-success",
            "status": "reviewed",
            "summary": "A tool call counts as a success only when its outcome is succeeded."
          },
          {
            "id": "the-advanced-trace-pages-at-1000-events",
            "status": "reviewed",
            "summary": "The advanced trace returns at most 1000 events per page, says more remain, and gives a cursor that continues after the last one."
          },
          {
            "id": "the-general-trace-lists-the-first-100-errors",
            "status": "reviewed",
            "summary": "The general trace lists at most the first 100 errors while still counting all of them."
          },
          {
            "id": "the-general-trace-lists-the-first-100-skills",
            "status": "reviewed",
            "summary": "The general trace lists at most the first 100 skills used while still counting all of them."
          },
          {
            "id": "trace-events-at-one-instant-order-by-source-attempt-seq",
            "status": "reviewed",
            "summary": "Events that occurred at the same instant are ordered by producer, then attempt, then seq."
          },
          {
            "id": "trace-maintenance-without-retention-deletes-nothing",
            "status": "reviewed",
            "summary": "Trace partition maintenance without a positive retention window is refused and deletes no events."
          },
          {
            "id": "trace-retention-keeps-whole-months",
            "status": "reviewed",
            "summary": "Trace maintenance deletes events older than the first day of the month holding the retention cutoff; events of that month stay."
          },
          {
            "id": "trace_events-attempt-check",
            "status": "candidate",
            "summary": "trace_events keeps check trace_events.attempt: attempt integer NOT NULL DEFAULT 1 CHECK (attempt >= 1)"
          },
          {
            "id": "trace_events-masked-check",
            "status": "candidate",
            "summary": "trace_events keeps check trace_events.masked: masked boolean NOT NULL DEFAULT false CHECK (masked)"
          },
          {
            "id": "trace_events_assign_ingest_seq",
            "status": "candidate",
            "summary": "trace_events keeps trigger trace_events_assign_ingest_seq: CREATE TRIGGER trace_events_assign_ingest_seq BEFORE INSERT ON trace_events FOR EACH ROW EXECUTE FUNCTION assign_trace_ingest_seq()"
          },
          {
