            "status": "candidate",
            "summary": "trace_events keeps trigger trace_events_dedupe_event_id: CREATE TRIGGER trace_events_dedupe_event_id BEFORE INSERT ON trace_events FOR EACH ROW EXECUTE FUNCTION dedupe_trace_event_id()"
          },
          {
            "id": "trace_events_event_id_key",
            "status": "candidate",
            "summary": "trace_events keeps unique-index trace_events_event_id_key: CREATE UNIQUE INDEX trace_events_event_id_key ON trace_events (event_id, occurred_at)"
          },
          {
            "id": "trace_events_guard_stream_seq",
            "status": "candidate",
            "summary": "trace_events keeps trigger trace_events_guard_stream_seq: CREATE TRIGGER trace_events_guard_stream_seq BEFORE INSERT ON trace_events FOR EACH ROW EXECUTE FUNCTION enforce_trace_stream_seq()"
          },
          {
            "id": "trace_events_immutable",
            "status": "candidate",
            "summary": "trace_events keeps trigger trace_events_immutable: CREATE TRIGGER trace_events_immutable BEFORE UPDATE OR DELETE ON trace_events FOR EACH ROW EXECUTE FUNCTION enforce_immutable()"
          }
