          "id": "batch",
          "status": "reviewed",
          "summary": "Runs one Skill Version against chosen Test Cases a set number of times, answers their questions as each Test Case's simulated user, and reports pass rates with intervals, with the Skill withheld and against a reference batch.",
          "implementation_path": "trial/batch"
        },
        "vocabulary": [
          {
            "id": "reference-batch",
            "status": "reviewed",
            "summary": "The evaluation batch that a comparison of two batches measures against; the other side is the candidate batch. An earlier set of trials, not a Run with the Skill withheld."
          },
          {
            "id": "skill-withheld",
            "status": "reviewed",
            "summary": "A Run that does not load the Skill under evaluation, so it measures the same Test Case without that Skill; an evaluation batch can run one beside every trial and compare the two. Not the same thing as a Reference batch."
          }
        ],
        "aggregates": [],
        "rules": [
          {
            "id": "a-batch-has-1-to-10-trials-and-1-to-50-distinct-test-cases",
            "status": "reviewed",
            "summary": "A batch is refused before anything is saved unless it has 1 to 10 trials and 1 to 50 test cases with no test case repeated."
          },
          {
            "id": "a-batch-is-read-only-within-its-workspace",
            "status": "reviewed",
            "summary": "A batch is read by its id together with the asking Workspace, so another Workspace's batch reads as not found."
          },
          {
            "id": "a-batch-needs-every-test-case-confirmed",
            "status": "reviewed",
            "summary": "A batch is refused as a whole, naming every unconfirmed test case, when any of its test cases lacks confirmed run permissions."
          },
          {
            "id": "a-batch-paused-for-thirty-days-stops",
            "status": "reviewed",
            "summary": "A batch paused for 30 days stops with reason paused_too_long; one paused for less stays paused and can be resumed from its next unrun trial."
          },
          {
            "id": "a-batch-report-is-read-only-under-its-own-skill",
            "status": "reviewed",
            "summary": "A batch report asked for under another Skill of the same Workspace answers not found."
          },
          {
            "id": "a-batch-settles-only-when-no-trial-is-open",
            "status": "reviewed",
            "summary": "A batch is marked settled only once none of its trials is still running or owed an answer; a paused batch is neither answered nor settled until it is resumed."
          },
          {
            "id": "a-batch-starts-no-trial-while-dispatch-is-paused",
            "status": "reviewed",
            "summary": "While dispatch is paused for every provider, by an orphan threshold or a P1 incident, an evaluation batch waits instead of creating its next trial, and starts it on the first advance after the halt lifts."
          },
          {
            "id": "a-batch-whose-creator-is-gone-stops",
            "status": "reviewed",
            "summary": "When a batch's creator no longer exists, the batch stops as creator_gone instead of starting another trial with no actor."
          },
          {
            "id": "a-batch-whose-test-case-is-gone-stops",
            "status": "reviewed",
            "summary": "When starting a batch's next trial finds its target gone, the batch stops with reason target_gone and starts no further trial."
          },
          {
            "id": "a-failed-trial-run-waits-for-its-judging",
            "status": "reviewed",
            "summary": "A trial whose run failed reads as running while its judging is under way, rather than as not evaluated."
          },
          {
            "id": "a-paired-difference-needs-two-pairs-for-an-interval",
            "status": "reviewed",
            "summary": "A paired difference gets a confidence interval only from two or more pairs; one pair gives the difference alone."
          },
          {
            "id": "a-paired-test-case-is-better-only-when-strictly-higher",
            "status": "reviewed",
            "summary": "A paired test case counts as better only when its rate is strictly higher, worse when strictly lower, and tied when equal."
          },
          {
            "id": "a-pass-rate-interval-is-a-95-percent-wilson-interval",
            "status": "reviewed",
            "summary": "A pass rate carries a 95 percent Wilson score interval, and none when nothing is judged."
          },
          {
            "id": "a-refused-simulated-answer-pauses-the-batch",
            "status": "reviewed",
            "summary": "When Run refuses a simulated person's answer because the owner's credit or run quota ran out, the batch pauses with that reason instead of closing the trial; a paused batch answers nothing, and resuming it gives the answers still owed."
          },
          {
            "id": "a-simulated-person-answers-only-where-the-test-case-has-facts",
            "status": "reviewed",
            "summary": "A batch answers a trial's questions as the simulated person only when the trial's conversation ended successfully, its test case has facts and the creator still exists; otherwise the questions are left for a real person."
          },
          {
            "id": "a-skill-effect-is-reported-only-when-the-skill-was-withheld",
            "status": "reviewed",
            "summary": "A batch report carries the skill-withheld arm and the skill effect only when the batch was created withholding the skill."
          },
          {
            "id": "a-test-case-says-when-its-prompt-varied",
            "status": "reviewed",
            "summary": "A test case is marked prompt-varied only when its trials started from more than one distinct prompt."
          },
          {
            "id": "a-trial-with-no-further-round-is-closed-not-failed",
            "status": "reviewed",
            "summary": "A simulated answer refused because the conversation has no further round closes the trial instead of failing the batch."
          },
          {
            "id": "batch-waits-only-on-a-passing-refusal",
            "status": "reviewed",
            "summary": "An evaluation batch waits when Run refuses a trial with a refusal Run says will pass on its own, including a run quota that could not be counted; pauses with the reason recorded when the refusal is one the owner can outwait or fix, a credit top-up or a used-up daily or windowed run quota; and stops with the reason recorded on any other refusal."
          },
          {
            "id": "batches-are-compared-only-on-test-cases-both-judged",
            "status": "reviewed",
            "summary": "Two batches are compared only on test cases judged in both; a test case judged in only one counts as unpaired, not as better, worse or tied."
          },
          {
            "id": "evaluation_batch_items-position-check",
            "status": "candidate",
            "summary": "evaluation_batch_items keeps check evaluation_batch_items.position: position integer NOT NULL CHECK (position >= 0)"
          },
          {
            "id": "evaluation_batch_items-run_id-unique",
            "status": "candidate",
            "summary": "evaluation_batch_items keeps unique evaluation_batch_items.run_id: run_id uuid UNIQUE"
          },
          {
            "id": "evaluation_batch_items-trial-check",
            "status": "candidate",
            "summary": "evaluation_batch_items keeps check evaluation_batch_items.trial: trial integer NOT NULL CHECK (trial >= 1)"
          },
          {
            "id": "evaluation_batches-status-check",
            "status": "candidate",
            "summary": "evaluation_batches keeps check evaluation_batches.status: status text NOT NULL DEFAULT 'launching' CHECK (status IN ('launching', 'launched', 'stopped'))"
          },
          {
            "id": "evaluation_batches-trials-check",
            "status": "candidate",
            "summary": "evaluation_batches keeps check evaluation_batches.trials: trials integer NOT NULL CHECK (trials BETWEEN 1 AND 10)"
          },
          {
            "id": "evaluation_batches_id_workspace_key",
            "status": "candidate",
            "summary": "evaluation_batches keeps unique evaluation_batches_id_workspace_key: CONSTRAINT evaluation_batches_id_workspace_key UNIQUE (id, workspace_id)"
          },
          {
            "id": "evaluation_batches_paused_has_time",
            "status": "candidate",
            "summary": "evaluation_batches keeps check evaluation_batches_paused_has_time: CONSTRAINT evaluation_batches_paused_has_time CHECK ((status = 'paused') = (paused_at IS NOT NULL))"
          },
          {
            "id": "evaluation_batches_settled_once_launched",
            "status": "candidate",
            "summary": "evaluation_batches keeps check evaluation_batches_settled_once_launched: CONSTRAINT evaluation_batches_settled_once_launched CHECK (settled_at IS NULL OR status = 'launched')"
          },
          {
            "id": "evaluation_batches_status_check",
            "status": "candidate",
            "summary": "evaluation_batches keeps check evaluation_batches_status_check: CONSTRAINT evaluation_batches_status_check CHECK (status IN ('launching', 'launched', 'paused', 'stopped'))"
          },
          {
            "id": "evaluation_batches_stop_has_reason",
            "status": "candidate",
            "summary": "evaluation_batches keeps check evaluation_batches_stop_has_reason: CONSTRAINT evaluation_batches_stop_has_reason CHECK ((status IN ('paused', 'stopped')) = (stop_reason IS NOT NULL))"
          },
          {
            "id": "only-a-met-trial-counts-as-passed",
            "status": "reviewed",
            "summary": "A trial counts as passed only when its outcome is met; a partially met trial is judged but not passed."
          },
          {
            "id": "only-judged-trials-enter-the-pass-rate",
            "status": "reviewed",
            "summary": "Only judged trials enter a pass rate; running, pending, awaiting-answer and not-evaluated trials count in neither its numerator nor its denominator."
          },
          {
            "id": "pass-at-k-is-unknown-until-the-trials-decide-it",
            "status": "reviewed",
            "summary": "pass@k is true once any trial passes, false only when all k are judged and none passed, and unknown otherwise."
          }
        ],
