        "value_objects": [],
        "rules_bound_through_collaborations": [
          {
            "rule": "a-run-starts-only-when-its-budget-is-reserved",
            "contexts": [
              "run"
            ],
            "statement": "When a credit ledger is configured, a Run is admitted only if the Workspace can reserve the run budget in force when it is created: the operator-set ceiling in run_model_budget_setting, or the deployment's when none is set. The Run keeps that ceiling in its policy snapshot, and its attempts run under it whatever the setting becomes later; a Workspace that cannot reserve it is refused with credit_balance.",
            "via": [
              "contracts/run-batch-trials-v1"
            ]
          },
          {
            "rule": "a-run-starts-only-when-the-platform-model-budget-left-covers-it",
            "contexts": [
              "run"
            ],
            "statement": "A trial Run is admitted only when the gateway's platform-wide model budget, less what is already spent and less the ceiling of every unfinished Run, still covers this Run's ceiling. Otherwise the preflight summary is blocked with platform_model_budget and creating the Run is refused for the same reason: no Run is created and nothing is charged, and the refusal says the budget recovers at 08:00 Taipei time. A budget or count that cannot be read admits the Run, because the gateway still enforces its own budget.",
            "via": [
              "contracts/run-batch-trials-v1"
            ]
          },
          {
            "rule": "an-access-restricted-skill-never-reaches-a-sandbox",
            "contexts": [
              "run"
            ],
            "statement": "A run of a skill under an access restriction is refused when it is created, and a run that was queued before the restriction was set fails as policy_refused at dispatch, before any sandbox receives the package; while the restriction cannot be read the run stays queued.",
            "via": [
              "contracts/run-batch-trials-v1"
            ]
          },
          {
            "rule": "an-origin-key-starts-only-one-skill-version",
            "contexts": [
              "run"
            ],
            "statement": "A caller's origin key returns the run it already started for the same Skill Version and is refused for a different version.",
            "via": [
              "contracts/run-batch-trials-v1"
            ]
          }
        ]
