            "summary": "A batch answers a trial's questions as the simulated person only when the trial's conversation ended successfully, its test case has facts and the creator still exists; otherwise the questions are left for a real person."
          },
          {
            "id": "a-skill-effect-is-reported-only-when-the-skill-was-withheld",
            "status": "reviewed",
            "summary": "A batch report carries the skill-withheld arm and the skill effect only when the batch was created withholding the skill."
          },
          {
            "id": "a-test-case-says-when-its-prompt-varied",
            "status": "reviewed",
            "summary": "A test case is marked prompt-varied only when its trials started from more than one distinct prompt."
          },
          {
            "id": "a-trial-with-no-further-round-is-closed-not-failed",
