            "contexts": [
              "run"
            ],
            "statement": "When a credit ledger is configured, a Run is admitted only if the Workspace can reserve the run budget in force when it is created: the operator-set ceiling in run_model_budget_setting, or the deployment's when none is set. The Run keeps that ceiling in its policy snapshot, and its attempts run under it whatever the setting becomes later; a Workspace that cannot reserve it is refused with credit_balance.",
            "via": [
              "contracts/run-batch-trials-v1"
            ]
          },
