      "id": "place-rejects-empty",
      "statement": "An empty order is rejected when placed.",
      "test_file": "src/orders/orders_test.go",
      "test": "TestPlaceRejectsEmpty",
      "check": "git -c \"alias.t=!cat src/orders/orders.go; grep -q ErrEmptyOrder src/orders/orders.go\" t",
      "enforcing": [
        "src/orders/orders.go:3-8"
      ],
      "mutate": {
        "file": "src/orders/orders.go",
        "find": "ErrEmptyOrder",
        "replace": "nil"
      }
    }
  ]
}

