{
  "name": "orders-rules",
  "context": "orders",
  "proposer": "agent-a",
  "intent": "Record the order rules.",
  "outcome": "The order rules are enforced by tests.",
  "scope": "orders",
  "ownership": {
    "decision": "orders owns its rules",
    "evidence": []
  },
  "boundary": {
    "decision": "no cross-context call",
    "evidence": []
  },
  "design": {
    "decision": "keep the rule in the aggregate",
    "domain_forces": [
      "a"
    ],
    "invariants_preserved": [
      "b"
    ],
    "rejected_alternatives": [
      "c"
    ]
  },
  "rules": [
    {
      "id": "place-rejects-empty",
      "statement": "An empty order is rejected when placed.",
      "test_file": "src/orders/orders_test.go",
      "test": "TestPlaceRejectsEmpty",
      "check": "git -c \"alias.t=!cat src/orders/orders.go; grep -q ErrEmptyOrder src/orders/orders.go\" t",
      "enforcing": [
        "src/orders/orders.go:3-8"
      ],
      "mutate": {
        "file": "src/orders/orders.go",
        "find": "ErrEmptyOrder",
        "replace": "nil"
      }
    }
  ]
}

