files.src/orders/orders.go:
package orders

func Place(o Order) error {
	if o.Empty() {
		return ErrEmptyOrder
	}
	return nil
}

func Check(o Order) error {
	if o.Missing() {
		return ErrMissingOrder
	}
	return nil
}

